/* ============================================================
   水墨武侠版素材（base64 内嵌）
   ============================================================ */
'use strict';

const ASSETS = {
  units: "data:image/png;base64,",
  icons: "data:image/png;base64,",
  skills: "data:image/png;base64,",
  fx: "data:image/png;base64,"
};
const BG_SRC = "data:image/jpeg;base64,";

const IMG = {};
function loadAssets() {
  for (const k in ASSETS) {
    const im = new Image();
    im.src = ASSETS[k];
    IMG[k] = im;
  }
  const b = new Image(); b.src = BG_SRC; IMG.bg = b;
}
function imgReady(k) { return IMG[k] && IMG[k].complete && IMG[k].naturalWidth > 0; }

const U_FRAME_W = 32, U_FRAME_H = 48;
const ICON_SIZE = 48;
const SLOT_ICON_IDX = { weapon:0, helm:1, chest:2, legs:3, boots:4, neck:5, ring:6, ring2:6, ring3:6, ring4:6, ring5:6, trinket:7 };
const SKILL_ICON_COUNT = 24;
const FX_SIZE = 48;
